1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string };
10	
11	type Scenario = {
12	  steps: { items: Item[] }[];
13	};
14	
15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const BASE_PREMIUMS: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	  moonstone: 25,
25	};
26	
27	const COMPONENT_BLOCK_SIZE = 3;
28	const COMPONENT_BLOCK_PREMIUM = 60;
29	
30	const sumOfIndividualBasePremiums = (items: Item[]): number =>
31	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
32	
33	const areAlike = (items: Item[]): boolean =>
34	  items.every((item) => item.type === items[0].type);
35	
36	const basePremiumOf = (items: Item[]): number => {
37	  if (items.length === COMPONENT_BLOCK_SIZE && areAlike(items)) {
38	    return COMPONENT_BLOCK_PREMIUM;
39	  }
40	
41	  return sumOfIndividualBasePremiums(items);
42	};
43	
44	const quotePremium = (items: Item[]): number => {
45	  const base = basePremiumOf(items);
46	  const withFirstInsuranceSurcharge = base + base * FIRST_INSURANCE_SURCHARGE;
47	
48	  return Math.ceil(withFirstInsuranceSurcharge + PROCESSING_FEE);
49	};
50	
51	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
52	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
53	});
